import React from "react";
import ReactDOM from "react-dom";

import {
  BrowserRouter as Router,
  Route,
  Switch,
  Redirect,
} from "react-router-dom";

import "./style.css";
import NotFound1, { NotFound } from "./views/NotFound1";
import Home from "./views/home";
import UserDetails from "./pages/UserDetails";
import BuilderDetails from "./pages/BuilderDetails";

const App = () => {
  return (
    <Router>
      <Switch>
        <Route component={NotFound1} exact path="/NotFound1" />
        <Route component={Home} exact path="/" />
        <Route component={UserDetails} exact path="/user/:id" />
        <Route component={BuilderDetails} exact path="/builder/:id" />
        <Route component={NotFound1} path="**" />
        <Redirect to="**" />
      </Switch>
    </Router>
  );
};

ReactDOM.render(<App />, document.getElementById("app"));
